// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blocknum, uint256 initialBalance) public {
        vm.assume(timestamp > block.timestamp);
        vm.warp(timestamp);
        vm.roll(blocknum);
        vm.deal(address(c), initialBalance);
        uint256 balBefore = address(c).balance;
        (bool ok,) = address(c).call{value: 10 ether}("");
        if (ok) {
            if (blocknum % 15 == 0) {
                assertTrue(address(c).balance == 0);
            } else {
                assertTrue(address(c).balance == balBefore + 10 ether - (blocknum % 15 == 0 ? balBefore : 0));
            }
        }
    }
}

